// ============================================================
// RateLimitConfig - 슬라이딩 윈도우 설정
// ============================================================

#[derive(Debug, Clone)]
pub struct RateLimitConfig {
    /// 슬라이딩 윈도우 크기 (초)
    pub window_secs: u64,
    /// ReadOnly 키 최대 요청 수 (윈도우당)
    pub readonly_limit: u64,
    /// ReadWrite 키 최대 요청 수
    pub readwrite_limit: u64,
    /// Admin 키 최대 요청 수
    pub admin_limit: u64,
}

impl Default for RateLimitConfig {
    fn default() -> Self {
        RateLimitConfig {
            window_secs:       60,
            readonly_limit:    60,
            readwrite_limit:  120,
            admin_limit:      600,
        }
    }
}

impl RateLimitConfig {
