use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

// ─── 이벤트 타입 ─────────────────────────────────────────

#[derive(Debug, Clone, PartialEq)]
pub enum EventKind {
    Insert,
    Update,
    Delete,
    SchemaChange,
    Custom(String),
}

impl EventKind {
    pub fn as_str(&self) -> &str {
        match self {
            EventKind::Insert       => "insert",
            EventKind::Update       => "update",
            EventKind::Delete       => "delete",
            EventKind::SchemaChange => "schema_change",
            EventKind::Custom(s)    => s.as_str(),
        }
    }

    pub fn from_str(s: &str) -> Self {
        match s {
            "insert"        => EventKind::Insert,
            "update"        => EventKind::Update,
            "delete"        => EventKind::Delete,
            "schema_change" => EventKind::SchemaChange,
            other           => EventKind::Custom(other.to_string()),
        }
    }
}

// ─── DbEvent ─────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct DbEvent {
    pub id:         u64,
    pub kind:       EventKind,
    pub intent:     String,
    pub table:      String,
    pub row_id:     Option<String>,
    pub payload:    serde_json::Value,
    pub timestamp:  u64,
}

impl DbEvent {
    pub fn new(
        kind: EventKind,
        intent: &str,
        table: &str,
        row_id: Option<&str>,
        payload: serde_json::Value,
    ) -> Self {
        DbEvent {
            id:        next_event_id(),
            kind,
            intent:    intent.to_string(),
            table:     table.to_string(),
            row_id:    row_id.map(|s| s.to_string()),
            payload,
            timestamp: unix_now(),
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "id":        self.id,
            "kind":      self.kind.as_str(),
            "intent":    self.intent,
            "table":     self.table,
            "row_id":    self.row_id,
            "payload":   self.payload,
            "timestamp": self.timestamp,
        })
    }

    /// SSE 형식: "data: <json>\n\n"
    pub fn to_sse(&self) -> String {
        format!("id: {}\nevent: {}\ndata: {}\n\n",
            self.id,
            self.kind.as_str(),
            self.to_json(),
        )
    }
}

// ─── 구독 필터 ────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct EventFilter {
    /// None = 모든 intent
    pub intent: Option<String>,
    /// None = 모든 이벤트 종류
    pub kinds: Option<Vec<EventKind>>,
}

impl EventFilter {
    pub fn all() -> Self {
        EventFilter { intent: None, kinds: None }
    }

    pub fn for_intent(intent: &str) -> Self {
        EventFilter { intent: Some(intent.to_string()), kinds: None }
    }

    pub fn matches(&self, event: &DbEvent) -> bool {
        if let Some(ref i) = self.intent {
            if &event.intent != i {
                return false;
            }
        }
        if let Some(ref kinds) = self.kinds {
            if !kinds.contains(&event.kind) {
                return false;
            }
        }
        true
    }

    pub fn from_json(json: &serde_json::Value) -> Self {
        let intent = json["intent"].as_str().map(|s| s.to_string());
        let kinds = json["kinds"].as_array().map(|arr| {
            arr.iter()
               .filter_map(|v| v.as_str())
               .map(EventKind::from_str)
               .collect()
        });
        EventFilter { intent, kinds }
    }
}

// ─── EventBus ────────────────────────────────────────────

pub struct EventBus {
    /// 최근 N개 이벤트 버퍼 (신규 구독자용)
    buffer:      Mutex<std::collections::VecDeque<DbEvent>>,
    buffer_size: usize,
    /// 구독자 id → (filter, sender)
    subscribers: Mutex<HashMap<u64, (EventFilter, std::sync::mpsc::SyncSender<DbEvent>)>>,
    next_sub_id: std::sync::atomic::AtomicU64,
}

impl EventBus {
    pub fn new(buffer_size: usize) -> Self {
        EventBus {
            buffer:      Mutex::new(std::collections::VecDeque::new()),
            buffer_size,
            subscribers: Mutex::new(HashMap::new()),
            next_sub_id: std::sync::atomic::AtomicU64::new(1),
        }
    }

    /// 이벤트 발행
    pub fn publish(&self, event: DbEvent) {
        // 버퍼에 저장
        {
            let mut buf = self.buffer.lock().unwrap();
            buf.push_back(event.clone());
            if buf.len() > self.buffer_size {
                buf.pop_front();
            }
        }

        // 구독자에게 전송 (끊긴 구독자 제거)
        let mut subs = self.subscribers.lock().unwrap();
        let mut dead = Vec::new();
        for (&id, (filter, tx)) in subs.iter() {
            if filter.matches(&event) {
                if tx.try_send(event.clone()).is_err() {
                    dead.push(id);
                }
            }
        }
        for id in dead {
            subs.remove(&id);
        }
    }

    /// 구독 등록 → 구독 ID, Receiver 반환
    pub fn subscribe(
        &self,
        filter: EventFilter,
    ) -> (u64, std::sync::mpsc::Receiver<DbEvent>) {
        let id = self.next_sub_id
            .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        let (tx, rx) = std::sync::mpsc::sync_channel(64);
        self.subscribers.lock().unwrap().insert(id, (filter, tx));
        (id, rx)
    }

    /// 구독 해제
    pub fn unsubscribe(&self, id: u64) {
        self.subscribers.lock().unwrap().remove(&id);
    }

    /// 현재 구독자 수
    pub fn subscriber_count(&self) -> usize {
        self.subscribers.lock().unwrap().len()
    }

    /// 버퍼의 최근 이벤트 조회
    pub fn recent_events(&self, limit: usize) -> Vec<DbEvent> {
        let buf = self.buffer.lock().unwrap();
        buf.iter().rev().take(limit).cloned().collect::<Vec<_>>()
            .into_iter().rev().collect()
    }

    /// 버퍼에서 특정 id 이후 이벤트 조회 (폴링용)
    pub fn events_since(&self, last_id: u64) -> Vec<DbEvent> {
        let buf = self.buffer.lock().unwrap();
        buf.iter()
           .filter(|e| e.id > last_id)
           .cloned()
           .collect()
    }

    pub fn stats_json(&self) -> serde_json::Value {
        let buf_len = self.buffer.lock().unwrap().len();
        let sub_count = self.subscribers.lock().unwrap().len();
        serde_json::json!({
            "buffer_size":    self.buffer_size,
            "buffered_events": buf_len,
            "active_subscribers": sub_count,
        })
    }
}

// ─── 공유 EventBus ───────────────────────────────────────

pub type SharedEventBus = Arc<EventBus>;

pub fn new_event_bus(buffer_size: usize) -> SharedEventBus {
    Arc::new(EventBus::new(buffer_size))
}

// ─── 내부 유틸 ───────────────────────────────────────────

static EVENT_COUNTER: std::sync::atomic::AtomicU64
    = std::sync::atomic::AtomicU64::new(1);

fn next_event_id() -> u64 {
    EVENT_COUNTER.fetch_add(1, std::sync::atomic::Ordering::SeqCst)
}

fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

