use std::sync::Arc;
use std::collections::HashMap;
use world_engine::events::{
    DbEvent, EventBus, EventFilter, EventKind,
    new_event_bus, SharedEventBus,
};
use world_engine::auth::{AuthManager, middleware::AuthConfig};

// ─── EventKind ────────────────────────────────────────────

#[test]
fn test_event_kind_as_str() {
    assert_eq!(EventKind::Insert.as_str(), "insert");
    assert_eq!(EventKind::Update.as_str(), "update");
    assert_eq!(EventKind::Delete.as_str(), "delete");
    assert_eq!(EventKind::SchemaChange.as_str(), "schema_change");
    assert_eq!(EventKind::Custom("ping".into()).as_str(), "ping");
}

#[test]
fn test_event_kind_from_str() {
    assert_eq!(EventKind::from_str("insert"),        EventKind::Insert);
    assert_eq!(EventKind::from_str("update"),        EventKind::Update);
    assert_eq!(EventKind::from_str("delete"),        EventKind::Delete);
    assert_eq!(EventKind::from_str("schema_change"), EventKind::SchemaChange);
    assert_eq!(EventKind::from_str("custom_op"),     EventKind::Custom("custom_op".into()));
}

// ─── DbEvent ─────────────────────────────────────────────

#[test]
fn test_db_event_new() {
    let e = DbEvent::new(
        EventKind::Insert, "Shop", "Product",
        Some("abc-123"),
        serde_json::json!({"name": "Widget"}),
    );
    assert_eq!(e.kind, EventKind::Insert);
    assert_eq!(e.intent, "Shop");
    assert_eq!(e.table, "Product");
    assert_eq!(e.row_id.as_deref(), Some("abc-123"));
    assert!(e.id > 0);
    assert!(e.timestamp > 0);
}

#[test]
fn test_db_event_unique_ids() {
    let e1 = DbEvent::new(EventKind::Insert, "A", "T", None, serde_json::Value::Null);
    let e2 = DbEvent::new(EventKind::Insert, "A", "T", None, serde_json::Value::Null);
    assert_ne!(e1.id, e2.id);
}

#[test]
fn test_db_event_to_json() {
    let e = DbEvent::new(EventKind::Update, "Inv", "Item", Some("x1"), serde_json::json!({}));
    let j = e.to_json();
    assert_eq!(j["kind"].as_str().unwrap(), "update");
    assert_eq!(j["intent"].as_str().unwrap(), "Inv");
    assert_eq!(j["table"].as_str().unwrap(), "Item");
    assert_eq!(j["row_id"].as_str().unwrap(), "x1");
}

#[test]
fn test_db_event_to_sse_format() {
    let e = DbEvent::new(EventKind::Delete, "S", "R", None, serde_json::Value::Null);
    let sse = e.to_sse();
    assert!(sse.starts_with("id: "));
    assert!(sse.contains("event: delete"));
    assert!(sse.contains("data: "));
    assert!(sse.ends_with("\n\n"));
}

// ─── EventFilter ─────────────────────────────────────────

#[test]
fn test_filter_all_matches_everything() {
    let f = EventFilter::all();
    let e = DbEvent::new(EventKind::Insert, "Any", "T", None, serde_json::Value::Null);
    assert!(f.matches(&e));
}

#[test]
fn test_filter_for_intent_matches() {
    let f = EventFilter::for_intent("Shop");
    let yes = DbEvent::new(EventKind::Insert, "Shop", "T", None, serde_json::Value::Null);
    let no  = DbEvent::new(EventKind::Insert, "Inv",  "T", None, serde_json::Value::Null);
    assert!(f.matches(&yes));
    assert!(!f.matches(&no));
}

#[test]
fn test_filter_kinds() {
    let f = EventFilter {
        intent: None,
        kinds: Some(vec![EventKind::Insert, EventKind::Update]),
    };
    let ins = DbEvent::new(EventKind::Insert, "X", "T", None, serde_json::Value::Null);
    let del = DbEvent::new(EventKind::Delete, "X", "T", None, serde_json::Value::Null);
    assert!(f.matches(&ins));
    assert!(!f.matches(&del));
}

#[test]
fn test_filter_from_json() {
    let j = serde_json::json!({ "intent": "Shop", "kinds": ["insert", "update"] });
    let f = EventFilter::from_json(&j);
    assert_eq!(f.intent.as_deref(), Some("Shop"));
    assert!(f.kinds.is_some());
}

// ─── EventBus ────────────────────────────────────────────

#[test]
fn test_publish_and_subscribe() {
    let bus = EventBus::new(10);
    let (_, rx) = bus.subscribe(EventFilter::all());

    bus.publish(DbEvent::new(EventKind::Insert, "S", "T", None, serde_json::Value::Null));

    let received = rx.recv().unwrap();
    assert_eq!(received.kind, EventKind::Insert);
}

#[test]
fn test_subscriber_count() {
    let bus = EventBus::new(10);
    assert_eq!(bus.subscriber_count(), 0);
    let (id, _rx) = bus.subscribe(EventFilter::all());
    assert_eq!(bus.subscriber_count(), 1);
    bus.unsubscribe(id);
    // 구독 해제 후 카운트
    assert_eq!(bus.subscriber_count(), 0);
}

#[test]
fn test_filter_by_intent_on_bus() {
    let bus = EventBus::new(10);
    let (_, rx_shop) = bus.subscribe(EventFilter::for_intent("Shop"));
    let (_, rx_all)  = bus.subscribe(EventFilter::all());

    bus.publish(DbEvent::new(EventKind::Insert, "Inv", "T", None, serde_json::Value::Null));
    bus.publish(DbEvent::new(EventKind::Insert, "Shop", "T", None, serde_json::Value::Null));

    // Shop 구독자는 Shop 이벤트만
    let e = rx_shop.recv().unwrap();
    assert_eq!(e.intent, "Shop");
    assert!(rx_shop.try_recv().is_err());

    // 전체 구독자는 둘 다
    assert!(rx_all.recv().is_ok());
    assert!(rx_all.recv().is_ok());
}

#[test]
fn test_buffer_recent_events() {
    let bus = EventBus::new(5);
    for i in 0..5u64 {
        bus.publish(DbEvent::new(EventKind::Insert, "X", "T", None, serde_json::json!({"i": i})));
    }
    let recent = bus.recent_events(3);
    assert_eq!(recent.len(), 3);
}

#[test]
fn test_buffer_overflow_drops_oldest() {
    let bus = EventBus::new(3);
    for _ in 0..5 {
        bus.publish(DbEvent::new(EventKind::Insert, "X", "T", None, serde_json::Value::Null));
    }
    let recent = bus.recent_events(10);
    assert_eq!(recent.len(), 3); // 버퍼 크기 초과분 제거
}

#[test]
fn test_events_since() {
    let bus = EventBus::new(20);
    let e1 = DbEvent::new(EventKind::Insert, "A", "T", None, serde_json::Value::Null);
    let id1 = e1.id;
    bus.publish(e1);
    bus.publish(DbEvent::new(EventKind::Update, "B", "T", None, serde_json::Value::Null));
    bus.publish(DbEvent::new(EventKind::Delete, "C", "T", None, serde_json::Value::Null));

    let since = bus.events_since(id1);
    assert_eq!(since.len(), 2); // id1 이후 2개
}

#[test]
fn test_stats_json() {
    let bus = EventBus::new(10);
    bus.publish(DbEvent::new(EventKind::Insert, "X", "T", None, serde_json::Value::Null));
    let j = bus.stats_json();
    assert_eq!(j["buffer_size"].as_u64().unwrap(), 10);
    assert_eq!(j["buffered_events"].as_u64().unwrap(), 1);
}

#[test]
fn test_new_event_bus_helper() {
    let bus: SharedEventBus = new_event_bus(50);
    assert_eq!(bus.subscriber_count(), 0);
}

// ─── Router 엔드포인트 ─────────────────────────────────────

fn parse_fl() -> world_engine::IntentGraph {
    world_engine::parse(r#"
intent Store {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Good { id: uuid @primary, name: string @required, }
    action list() { return 0; }
}
"#).unwrap()
}

fn headers(pairs: &[(&str, &str)]) -> HashMap<String, String> {
    pairs.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect()
}

#[test]
fn test_router_events_disabled() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/events", "");
    assert_eq!(status, 200);
    assert_eq!(json["enabled"].as_bool().unwrap(), false);
}

#[test]
fn test_router_events_enabled_empty() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
    let bus = new_event_bus(50);
    let mut router = Router::from_graph(graph).with_event_bus(Arc::clone(&bus));
    let (status, json) = router.handle(&mut { result.db }, "GET", "/events", "");
    assert_eq!(status, 200);
    assert_eq!(json["enabled"].as_bool().unwrap(), true);
    assert_eq!(json["events"].as_array().unwrap().len(), 0);
}

#[test]
fn test_router_publish_and_poll() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
    let bus = new_event_bus(50);
    let mut router = Router::from_graph(graph).with_event_bus(Arc::clone(&bus));
    let mut db = result.db;

    // 커스텀 이벤트 발행
    let (s, j) = router.handle(&mut db, "POST", "/events/publish",
        r#"{"kind":"custom","intent":"Store","table":"Good","payload":{"msg":"hello"}}"#);
    assert_eq!(s, 200);
    assert!(j["event_id"].as_u64().is_some());

    // 폴링
    let (s, j) = router.handle(&mut db, "GET", "/events", "");
    assert_eq!(s, 200);
    assert_eq!(j["events"].as_array().unwrap().len(), 1);
    assert_eq!(j["events"][0]["kind"].as_str().unwrap(), "custom");
}

#[test]
fn test_router_events_since_last_id() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
    let bus = new_event_bus(50);
    let mut router = Router::from_graph(graph).with_event_bus(Arc::clone(&bus));
    let mut db = result.db;

    // 이벤트 2개 발행
    router.handle(&mut db, "POST", "/events/publish",
        r#"{"kind":"insert","intent":"Store","table":"Good","payload":{}}"#);
    let (_, j1) = router.handle(&mut db, "POST", "/events/publish",
        r#"{"kind":"update","intent":"Store","table":"Good","payload":{}}"#);
    let first_event_id = j1["event_id"].as_u64().unwrap();

    // last_id로 폴링
    let path = format!("/events?last_id={}", first_event_id - 1);
    let (s, j) = router.handle(&mut db, "GET", &path, "");
    assert_eq!(s, 200);
    assert_eq!(j["events"].as_array().unwrap().len(), 1);
}

#[test]
fn test_router_events_stats() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
    let bus = new_event_bus(50);
    let mut router = Router::from_graph(graph).with_event_bus(Arc::clone(&bus));
    let (status, json) = router.handle(&mut { result.db }, "GET", "/events/stats", "");
    assert_eq!(status, 200);
    assert!(json["buffer_size"].as_u64().is_some());
}

#[test]
fn test_mutate_emits_schema_change_event() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    use world_engine::auth::{AuthManager, middleware::AuthConfig};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
    let bus = new_event_bus(50);
    let am = Arc::new(AuthManager::new(AuthConfig::new("secret")));
    let rw_key = am.issue_api_key("writer", world_engine::auth::apikey::Permission::ReadWrite);
    let mut router = Router::from_graph(graph)
        .with_event_bus(Arc::clone(&bus))
        .with_auth(Arc::clone(&am));
    let mut db = result.db;
    let hdrs = headers(&[("x-api-key", &rw_key)]);

    router.handle_with_headers(
        &mut db, "POST", "/mutate",
        r#"{"op":"add_field","intent":"Store","schema":"Good","field_name":"price","field_type":"f64"}"#,
        &hdrs,
    );

    // 이벤트 버퍼에 schema_change 확인
    let events = bus.recent_events(5);
    assert!(!events.is_empty());
    assert_eq!(events[0].kind, EventKind::SchemaChange);
    assert_eq!(events[0].intent, "Store");
}

