fn test_mutate_emits_schema_change_event() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    use world_engine::auth::{AuthManager, middleware::AuthConfig};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
    let bus = new_event_bus(50);
