// ============================================================
// Schema Migration Engine
// ============================================================
// .fl 스키마 변경 이력 관리 및 마이그레이션 적용
// 외부 crate 없이 순수 Rust std + serde_json
// ============================================================

use std::time::{SystemTime, UNIX_EPOCH};
use crate::ast::IntentGraph;
use crate::mutation::{MutationEngine, MutationOp};

// ─── MigrationKind ───────────────────────────────────────

#[derive(Debug, Clone, PartialEq)]
pub enum MigrationKind {
    AddField,
    RemoveField,
    RenameField,
    AddIntent,
    RemoveIntent,
    AddAction,
    RemoveAction,
    Custom(String),
}

impl MigrationKind {
    pub fn as_str(&self) -> &str {
        match self {
            MigrationKind::AddField     => "add_field",
            MigrationKind::RemoveField  => "remove_field",
            MigrationKind::RenameField  => "rename_field",
            MigrationKind::AddIntent    => "add_intent",
            MigrationKind::RemoveIntent => "remove_intent",
            MigrationKind::AddAction    => "add_action",
            MigrationKind::RemoveAction => "remove_action",
            MigrationKind::Custom(s)    => s.as_str(),
        }
    }

    pub fn from_str(s: &str) -> Self {
        match s {
            "add_field"     => MigrationKind::AddField,
            "remove_field"  => MigrationKind::RemoveField,
            "rename_field"  => MigrationKind::RenameField,
            "add_intent"    => MigrationKind::AddIntent,
            "remove_intent" => MigrationKind::RemoveIntent,
            "add_action"    => MigrationKind::AddAction,
            "remove_action" => MigrationKind::RemoveAction,
            other           => MigrationKind::Custom(other.to_string()),
        }
    }
}

// ─── Migration (단일 변경 단계) ──────────────────────────

#[derive(Debug, Clone)]
pub struct Migration {
    pub version:     u64,
    pub description: String,
    pub kind:        MigrationKind,
    pub payload:     serde_json::Value,
    pub applied_at:  Option<u64>,
    pub checksum:    u64,
}

impl Migration {
    pub fn new(version: u64, description: &str, kind: MigrationKind, payload: serde_json::Value) -> Self {
        let checksum = fnv1a64(format!("{}{}{:?}", version, description, payload).as_bytes());
        Migration {
            version,
            description: description.to_string(),
            kind,
            payload,
            applied_at: None,
            checksum,
        }
    }

    pub fn is_applied(&self) -> bool {
        self.applied_at.is_some()
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "version":     self.version,
            "description": self.description,
            "kind":        self.kind.as_str(),
            "payload":     self.payload,
            "applied_at":  self.applied_at,
            "checksum":    self.checksum,
            "applied":     self.is_applied(),
        })
    }

    pub fn from_json(v: &serde_json::Value) -> Option<Self> {
        let version     = v["version"].as_u64()?;
        let description = v["description"].as_str().unwrap_or("").to_string();
        let kind        = MigrationKind::from_str(v["kind"].as_str().unwrap_or("custom"));
        let payload     = v["payload"].clone();
        let applied_at  = v["applied_at"].as_u64();
        let checksum    = fnv1a64(format!("{}{}{:?}", version, description, payload).as_bytes());
        Some(Migration { version, description, kind, payload, applied_at, checksum })
    }
}

// ─── MigrationPlan (다단계 마이그레이션) ────────────────

#[derive(Debug, Clone)]
pub struct MigrationPlan {
    pub name:       String,
    pub steps:      Vec<Migration>,
}

impl MigrationPlan {
    pub fn new(name: &str) -> Self {
        MigrationPlan { name: name.to_string(), steps: Vec::new() }
    }

    pub fn add_step(mut self, step: Migration) -> Self {
        self.steps.push(step);
        self
    }

    pub fn pending_steps(&self) -> Vec<&Migration> {
        self.steps.iter().filter(|s| !s.is_applied()).collect()
    }

    pub fn applied_steps(&self) -> Vec<&Migration> {
        self.steps.iter().filter(|s| s.is_applied()).collect()
    }

    pub fn is_complete(&self) -> bool {
        self.steps.iter().all(|s| s.is_applied())
    }

    pub fn next_version(&self) -> u64 {
        self.steps.iter().map(|s| s.version).max().unwrap_or(0) + 1
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "name":     self.name,
            "total":    self.steps.len(),
            "applied":  self.applied_steps().len(),
            "pending":  self.pending_steps().len(),
            "complete": self.is_complete(),
            "steps":    self.steps.iter().map(|s| s.to_json()).collect::<Vec<_>>(),
        })
    }
}

// ─── MigrationResult ─────────────────────────────────────

#[derive(Debug, Clone)]
pub struct MigrationResult {
    pub version:    u64,
    pub success:    bool,
    pub message:    String,
    pub duration_ms: u64,
}

impl MigrationResult {
    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "version":     self.version,
            "success":     self.success,
            "message":     self.message,
            "duration_ms": self.duration_ms,
        })
    }
}

// ─── MigrationEngine ─────────────────────────────────────

pub struct MigrationEngine {
    pub plan: MigrationPlan,
    mutation: MutationEngine,
}

impl MigrationEngine {
    pub fn new(plan_name: &str) -> Self {
        MigrationEngine {
            plan: MigrationPlan::new(plan_name),
            mutation: MutationEngine::new(),
        }
    }

    /// 마이그레이션 단계 추가
    pub fn add(mut self, step: Migration) -> Self {
        self.plan.steps.push(step);
        self
    }

    /// 단일 단계 적용
    pub fn apply_one(
        &mut self,
        version: u64,
        graph: &mut IntentGraph,
    ) -> MigrationResult {
        let start = unix_now_millis();

        // 해당 버전 찾기
        let step = match self.plan.steps.iter_mut().find(|s| s.version == version) {
            None => return MigrationResult {
                version,
                success: false,
                message: format!("버전 {} 마이그레이션 없음", version),
                duration_ms: 0,
            },
            Some(s) => s,
        };

        if step.is_applied() {
            return MigrationResult {
                version,
                success: true,
                message: format!("버전 {} 이미 적용됨", version),
                duration_ms: unix_now_millis() - start,
            };
        }

        // MutationOp로 변환하여 적용
        let op = match MutationOp::from_json(&step.payload) {
            Ok(op) => op,
            Err(e) => return MigrationResult {
                version,
                success: false,
                message: format!("Op 파싱 실패: {}", e),
                duration_ms: unix_now_millis() - start,
            },
        };

        let (success, msg) = self.mutation.apply(graph, op);
        let duration_ms = unix_now_millis() - start;

        if success {
            // 적용 시각 기록
            let applied_version = version;
            if let Some(s) = self.plan.steps.iter_mut().find(|s| s.version == applied_version) {
                s.applied_at = Some(unix_now());
            }
        }

        MigrationResult { version, success, message: msg, duration_ms }
    }

    /// 모든 미적용 단계 순서대로 적용
    pub fn apply_all(&mut self, graph: &mut IntentGraph) -> Vec<MigrationResult> {
        let pending: Vec<u64> = self.plan.steps
            .iter()
            .filter(|s| !s.is_applied())
            .map(|s| s.version)
            .collect();

        pending.into_iter()
            .map(|v| self.apply_one(v, graph))
            .collect()
    }

    /// 특정 버전까지 적용 (롤링 업그레이드)
    pub fn apply_up_to(&mut self, target: u64, graph: &mut IntentGraph) -> Vec<MigrationResult> {
        let pending: Vec<u64> = self.plan.steps
            .iter()
            .filter(|s| !s.is_applied() && s.version <= target)
            .map(|s| s.version)
            .collect();

        pending.into_iter()
            .map(|v| self.apply_one(v, graph))
            .collect()
    }

    pub fn status_json(&self) -> serde_json::Value {
        self.plan.to_json()
    }
}

// ─── 편의 함수: DSL 스타일 마이그레이션 빌더 ────────────

pub fn add_field_migration(
    version: u64,
    desc: &str,
    intent: &str,
    schema: &str,
    field: &str,
    field_type: &str,
) -> Migration {
    Migration::new(
        version, desc,
        MigrationKind::AddField,
        serde_json::json!({
            "op": "add_field",
            "intent": intent,
            "schema": schema,
            "field_name": field,
            "field_type": field_type,
        }),
    )
}

pub fn remove_field_migration(
    version: u64,
    desc: &str,
    intent: &str,
    schema: &str,
    field: &str,
) -> Migration {
    Migration::new(
        version, desc,
        MigrationKind::RemoveField,
        serde_json::json!({
            "op": "remove_field",
            "intent": intent,
            "schema": schema,
            "field_name": field,
        }),
    )
}

pub fn rename_field_migration(
    version: u64,
    desc: &str,
    intent: &str,
    schema: &str,
    old_name: &str,
    new_name: &str,
) -> Migration {
    Migration::new(
        version, desc,
        MigrationKind::RenameField,
        serde_json::json!({
            "op": "rename_field",
            "intent": intent,
            "schema": schema,
            "old_name": old_name,
            "new_name": new_name,
        }),
    )
}

// ─── 내부 유틸 ───────────────────────────────────────────

fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn unix_now_millis() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64
}

fn fnv1a64(data: &[u8]) -> u64 {
    let mut hash: u64 = 0xcbf29ce484222325;
    for &b in data {
        hash ^= b as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

