    }

    pub fn next_version(&self) -> u64 {
        self.steps.iter().map(|s| s.version).max().unwrap_or(0) + 1
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "name":     self.name,
            "total":    self.steps.len(),
            "applied":  self.applied_steps().len(),
            "pending":  self.pending_steps().len(),
            "complete": self.is_complete(),
            "steps":    self.steps.iter().map(|s| s.to_json()).collect::<Vec<_>>(),
        })
    }
}

// ─── MigrationResult ─────────────────────────────────────

#[derive(Debug, Clone)]
pub struct MigrationResult {
    pub version:    u64,
    pub success:    bool,
    pub message:    String,
    pub duration_ms: u64,
}

impl MigrationResult {
    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "version":     self.version,
            "success":     self.success,
            "message":     self.message,
            "duration_ms": self.duration_ms,
        })
    }
}

// ─── MigrationEngine ─────────────────────────────────────

pub struct MigrationEngine {
    pub plan: MigrationPlan,
    mutation: MutationEngine,
}

impl MigrationEngine {
    pub fn new(plan_name: &str) -> Self {
        MigrationEngine {
            plan: MigrationPlan::new(plan_name),
            mutation: MutationEngine::new(),
        }
    }

    /// 마이그레이션 단계 추가
    pub fn add(mut self, step: Migration) -> Self {
        self.plan.steps.push(step);
        self
    }

    /// 단일 단계 적용
    pub fn apply_one(
        &mut self,
        version: u64,
        graph: &mut IntentGraph,
    ) -> MigrationResult {
        let start = unix_now_millis();

        // 해당 버전 찾기
        let step = match self.plan.steps.iter_mut().find(|s| s.version == version) {
            None => return MigrationResult {
                version,
                success: false,
                message: format!("버전 {} 마이그레이션 없음", version),
                duration_ms: 0,
            },
            Some(s) => s,
        };

        if step.is_applied() {
            return MigrationResult {
                version,
                success: true,
                message: format!("버전 {} 이미 적용됨", version),
                duration_ms: unix_now_millis() - start,
            };
        }

        // MutationOp로 변환하여 적용
        let op = match MutationOp::from_json(&step.payload) {
            Ok(op) => op,
            Err(e) => return MigrationResult {
                version,
                success: false,
                message: format!("Op 파싱 실패: {}", e),
                duration_ms: unix_now_millis() - start,
            },
        };

        let (success, msg) = self.mutation.apply(graph, op);
        let duration_ms = unix_now_millis() - start;

        if success {
            // 적용 시각 기록
            let applied_version = version;
            if let Some(s) = self.plan.steps.iter_mut().find(|s| s.version == applied_version) {
                s.applied_at = Some(unix_now());
            }
        }

        MigrationResult { version, success, message: msg, duration_ms }
    }

    /// 모든 미적용 단계 순서대로 적용
    pub fn apply_all(&mut self, graph: &mut IntentGraph) -> Vec<MigrationResult> {
        let pending: Vec<u64> = self.plan.steps
            .iter()
            .filter(|s| !s.is_applied())
            .map(|s| s.version)
            .collect();

        pending.into_iter()
            .map(|v| self.apply_one(v, graph))
            .collect()
    }

    /// 특정 버전까지 적용 (롤링 업그레이드)
    pub fn apply_up_to(&mut self, target: u64, graph: &mut IntentGraph) -> Vec<MigrationResult> {
        let pending: Vec<u64> = self.plan.steps
            .iter()
            .filter(|s| !s.is_applied() && s.version <= target)
            .map(|s| s.version)
            .collect();

        pending.into_iter()
            .map(|v| self.apply_one(v, graph))
            .collect()
    }

    pub fn status_json(&self) -> serde_json::Value {
        self.plan.to_json()
    }
}

// ─── 편의 함수: DSL 스타일 마이그레이션 빌더 ────────────

pub fn add_field_migration(
    version: u64,
    desc: &str,
    intent: &str,
    schema: &str,
    field: &str,
    field_type: &str,
) -> Migration {
    Migration::new(
        version, desc,
        MigrationKind::AddField,
        serde_json::json!({
            "op": "add_field",
            "intent": intent,
            "schema": schema,
            "field_name": field,
            "field_type": field_type,
        }),
    )
}

pub fn remove_field_migration(
    version: u64,
    desc: &str,
    intent: &str,
    schema: &str,
    field: &str,
) -> Migration {
    Migration::new(
        version, desc,
        MigrationKind::RemoveField,
        serde_json::json!({
            "op": "remove_field",
            "intent": intent,
            "schema": schema,
            "field_name": field,
        }),
    )
}

pub fn rename_field_migration(
    version: u64,
    desc: &str,
    intent: &str,
    schema: &str,
    old_name: &str,
    new_name: &str,
) -> Migration {
    Migration::new(
        version, desc,
        MigrationKind::RenameField,
        serde_json::json!({
            "op": "rename_field",
            "intent": intent,
            "schema": schema,
            "old_name": old_name,
            "new_name": new_name,
        }),
    )
}

// ─── 내부 유틸 ───────────────────────────────────────────

fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn unix_now_millis() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64
}

fn fnv1a64(data: &[u8]) -> u64 {
    let mut hash: u64 = 0xcbf29ce484222325;
    for &b in data {
        hash ^= b as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

