use std::sync::{Arc, Mutex};
use crate::ast::{FlType, IntentGraph};
use crate::synthesizer::kimdb::KimDB;
use crate::synthesizer::executor::ActionExecutor;
use crate::renderer::ViewRenderer;
use crate::lifecycle::LifecycleManager;
use crate::deficiency::DeficiencyDetector;
use crate::hotreload::HotReloader;
use crate::federation::FederationMerger;
use crate::mutation::{MutationEngine, MutationOp};
use crate::emitter::{self, EmitTarget};
use crate::synthesizer::persist::PersistManager;
use crate::auth::{AuthManager, AuthResult};
use crate::auth::middleware::AuthMiddleware;
use crate::events::{EventBus, DbEvent, EventKind, EventFilter, SharedEventBus};
use super::codec;

// ============================================================
// 라우트 엔트리
// ============================================================

#[derive(Debug, Clone)]
pub struct Route {
    pub intent: String,
    pub action: String,
    pub params: Vec<(String, FlType)>,
    pub method: &'static str,
    pub path: String,
}

// ============================================================
// Router - IntentGraph → 라우트 테이블
// ============================================================

pub struct Router {
    pub routes: Vec<Route>,
    pub graph: IntentGraph,
    pub lifecycle: Arc<Mutex<LifecycleManager>>,
    pub reloader: Option<Arc<HotReloader>>,
    pub federation: Option<Arc<Mutex<FederationMerger>>>,
    pub mutation: Arc<Mutex<MutationEngine>>,
    pub persist: Option<Arc<PersistManager>>,
    pub auth: Option<Arc<AuthManager>>,
    pub event_bus: Option<SharedEventBus>,
}

impl Router {
    fn build_routes(graph: &IntentGraph) -> Vec<Route> {
        let mut routes = Vec::new();
        for intent in &graph.intents {
            for schema in &intent.schemas {
                routes.push(Route {
                    intent: intent.name.clone(),
                    action: format!("_select_{}", schema.name),
                    params: vec![],
                    method: "GET",
                    path: format!("/{}/{}", intent.name, schema.name),
                });
            }
        }
        for intent in &graph.intents {
            for action in &intent.actions {
                routes.push(Route {
                    intent: intent.name.clone(),
                    action: action.name.clone(),
                    params: action.params.iter()
                        .map(|p| (p.name.clone(), p.param_type.clone()))
                        .collect(),
                    method: "POST",
                    path: format!("/{}/{}", intent.name, action.name),
                });
            }
        }
        routes
    }

    pub fn from_graph(graph: IntentGraph) -> Self {
        let lifecycle = Arc::new(Mutex::new(LifecycleManager::from_graph(&graph)));
        let routes = Self::build_routes(&graph);
        Router {
            routes,
            graph,
            lifecycle,
            reloader: None,
            federation: None,
            mutation: Arc::new(Mutex::new(MutationEngine::new())),
            persist: None,
            auth: None,
            event_bus: None,
        }
    }

    pub fn with_reloader(mut self, reloader: Arc<HotReloader>) -> Self {
        self.reloader = Some(reloader);
        self
    }

    pub fn with_federation(mut self, merger: FederationMerger) -> Self {
        self.federation = Some(Arc::new(Mutex::new(merger)));
        self
    }

    pub fn with_persist(mut self, pm: Arc<PersistManager>) -> Self {
        self.persist = Some(pm);
        self
    }

    pub fn with_auth(mut self, am: Arc<AuthManager>) -> Self {
        self.auth = Some(am);
        self
    }

    pub fn with_event_bus(mut self, bus: SharedEventBus) -> Self {
        self.event_bus = Some(bus);
        self
    }

    pub fn route_list(&self) -> serde_json::Value {
        let list: Vec<serde_json::Value> = self.routes.iter().map(|r| {
            let params: Vec<serde_json::Value> = r.params.iter().map(|(name, ft)| {
                serde_json::json!({ "name": name, "type": format!("{}", ft) })
            }).collect();
            serde_json::json!({
                "method": r.method,
                "path": r.path,
                "params": params,
            })
        }).collect();
        serde_json::json!({ "routes": list, "count": list.len() })
    }

    // ─── 요청 처리 (IO 없음, 테스트 가능) ──────────────────────

    pub fn handle(
        &mut self,
        db: &mut KimDB,
        method: &str,
        path: &str,
        body: &str,
    ) -> (u16, serde_json::Value) {
        self.handle_with_headers(db, method, path, body, &std::collections::HashMap::new())
    }

    pub fn handle_with_headers(
        &mut self,
        db: &mut KimDB,
        method: &str,
        path: &str,
        body: &str,
        headers: &std::collections::HashMap<String, String>,
    ) -> (u16, serde_json::Value) {
        // ── 인증 검사 ─────────────────────────────────────────
        if let Some(am) = &self.auth {
            let required = am.config.required_permission(method, path);
            if required.is_some() {
                let auth_result = am.authenticate(headers);
                if !AuthMiddleware::authorize(&auth_result, required) {
                    let msg = match &auth_result {
                        AuthResult::Denied(m) => m.clone(),
                        _ => "권한 부족".into(),
                    };
                    return (401, serde_json::json!({ "error": msg, "path": path }));
                }

                // ── Rate Limit 검사 (인증 성공 후) ──────────
                if let AuthResult::Allowed(perm) = &auth_result {
                    let key_id = headers
                        .get("x-api-key")
                        .or_else(|| headers.get("X-Api-Key"))
                        .cloned()
                        .unwrap_or_else(|| "bearer:anon".to_string());
                    if let Some(rl) = am.check_rate_limit(&key_id, perm) {
                        if !rl.allowed {
                            return (429, serde_json::json!({
                                "error":      "요청 한도 초과",
                                "limit":      rl.limit,
                                "remaining":  0,
                                "reset_secs": rl.reset_secs,
                            }));
                        }
                    }
                }
            }
        }

        // ── 인증 관리 API ─────────────────────────────────────

        // GET /auth/status → 인증 시스템 상태
        if method == "GET" && path == "/auth/status" {
            return match &self.auth {
                Some(am) => (200, am.status_json()),
                None     => (200, serde_json::json!({ "enabled": false })),
            };
        }

        // POST /auth/token → API Key로 토큰 발급
        if method == "POST" && path == "/auth/token" {
            return match &self.auth {
                None => (400, serde_json::json!({ "error": "인증 비활성화 상태" })),
                Some(am) => {
                    let auth_res = am.authenticate(headers);
                    match auth_res {
                        AuthResult::Allowed(perm) => {
                            let json: serde_json::Value = serde_json::from_str(body)
                                .unwrap_or(serde_json::Value::Null);
                            let subject = json["subject"].as_str()
                                .unwrap_or("anonymous");
                            let token = am.issue_token(subject, perm);
                            (200, serde_json::json!({ "token": token, "type": "Bearer" }))
                        }
                        AuthResult::Denied(msg) => (401, serde_json::json!({ "error": msg })),
                        AuthResult::Public => (400, serde_json::json!({ "error": "API Key 필요" })),
                    }
                }
            };
        }

        // POST /auth/revoke → 토큰 폐기
        if method == "POST" && path == "/auth/revoke" {
            return match &self.auth {
                None => (400, serde_json::json!({ "error": "인증 비활성화 상태" })),
                Some(am) => {
                    let json: serde_json::Value = serde_json::from_str(body)
                        .unwrap_or(serde_json::Value::Null);
                    if let Some(token) = json["token"].as_str() {
                        am.revoke_token(token);
                        (200, serde_json::json!({ "ok": true }))
                    } else {
                        (400, serde_json::json!({ "error": "'token' 필드 없음" }))
                    }
                }
            };
        }

        // GET /auth/keys → API Key 목록 (Admin only)
        if method == "GET" && path == "/auth/keys" {
            return match &self.auth {
                None => (200, serde_json::json!({ "enabled": false, "keys": [] })),
                Some(am) => {
                    let store = am.key_store.lock().unwrap();
                    (200, serde_json::json!({ "keys": store.list_json(), "count": store.count() }))
                }
            };
        }

        // POST /auth/keys → 새 API Key 발급 (Admin only)
        if method == "POST" && path == "/auth/keys" {
            return match &self.auth {
                None => (400, serde_json::json!({ "error": "인증 비활성화 상태" })),
                Some(am) => {
                    let json: serde_json::Value = serde_json::from_str(body)
                        .unwrap_or(serde_json::Value::Null);
                    let label = json["label"].as_str().unwrap_or("unnamed");
                    let perm_str = json["permission"].as_str().unwrap_or("readonly");
                    let perm = crate::auth::apikey::Permission::from_str(perm_str);
                    let key = am.issue_api_key(label, perm);
                    (200, serde_json::json!({ "key": key, "label": label, "permission": perm_str }))
                }
            };
        }

        // GET /auth/ratelimit → Rate Limit 통계 (Admin only)
        if method == "GET" && path == "/auth/ratelimit" {
            return match &self.auth {
                None     => (200, serde_json::json!({ "enabled": false })),
                Some(am) => (200, am.rate_limit_stats_json()),
            };
        }

        // DELETE /auth/ratelimit → 특정 키 Rate Limit 초기화 (Admin only)
        if method == "DELETE" && path == "/auth/ratelimit" {
            return match &self.auth {
                None => (400, serde_json::json!({ "error": "인증 비활성화 상태" })),
                Some(am) => {
                    let json: serde_json::Value = serde_json::from_str(body)
                        .unwrap_or(serde_json::Value::Null);
                    match &am.rate_limiter {
                        None => (400, serde_json::json!({ "error": "Rate Limiting 비활성화 상태" })),
                        Some(rl) => {
                            if let Some(key) = json["key"].as_str() {
                                rl.reset_key(key);
                                (200, serde_json::json!({ "ok": true, "reset_key": key }))
                            } else {
                                rl.reset_all();
                                (200, serde_json::json!({ "ok": true, "reset": "all" }))
                            }
                        }
                    }
                }
            };
        }

        // ── 이벤트 API ───────────────────────────────────────

        // GET /events → 최근 이벤트 폴링 (last_id 파라미터 지원)
        if method == "GET" && (path == "/events" || path.starts_with("/events?")) {
            return match &self.event_bus {
                None => (200, serde_json::json!({
                    "enabled": false,
                    "events": [],
                })),
                Some(bus) => {
                    // ?last_id=N 파싱
                    let last_id: u64 = if let Some(qs) = path.find('?') {
                        let query = &path[qs + 1..];
                        query.split('&')
                            .find(|p| p.starts_with("last_id="))
                            .and_then(|p| p["last_id=".len()..].parse().ok())
                            .unwrap_or(0)
                    } else {
                        0
                    };
                    let events: Vec<serde_json::Value> = bus
                        .events_since(last_id)
                        .iter()
                        .map(|e| e.to_json())
                        .collect();
                    (200, serde_json::json!({
                        "enabled": true,
                        "events": events,
                        "count": events.len(),
                    }))
                }
            };
        }

        // GET /events/stats → EventBus 통계
        if method == "GET" && path == "/events/stats" {
            return match &self.event_bus {
                None  => (200, serde_json::json!({ "enabled": false })),
                Some(bus) => (200, bus.stats_json()),
            };
        }

        // POST /events/publish → 커스텀 이벤트 발행
        if method == "POST" && path == "/events/publish" {
            return match &self.event_bus {
                None => (400, serde_json::json!({ "error": "EventBus 비활성화 상태" })),
                Some(bus) => {
                    let json: serde_json::Value = serde_json::from_str(body)
                        .unwrap_or(serde_json::Value::Null);
                    let kind  = json["kind"].as_str().unwrap_or("custom");
                    let intent = json["intent"].as_str().unwrap_or("_global");
                    let table  = json["table"].as_str().unwrap_or("");
                    let row_id = json["row_id"].as_str();
                    let payload = json["payload"].clone();
                    let event = DbEvent::new(
                        EventKind::from_str(kind),
                        intent, table, row_id, payload,
                    );
                    let eid = event.id;
                    bus.publish(event);
                    (200, serde_json::json!({ "ok": true, "event_id": eid }))
                }
            };
        }

        // GET / 또는 GET /routes → 라우트 목록
        if method == "GET" && (path == "/" || path == "/routes") {
            return (200, self.route_list());
        }

        // GET /health
        if method == "GET" && path == "/health" {
            return (200, serde_json::json!({
                "status": "ok",
                "tables": db.table_names(),
            }));
        }

        // GET /views → 전체 뷰 인덱스
        if method == "GET" && path == "/views" {
            let renderer = ViewRenderer::new(&self.graph);
            return (200, renderer.view_index());
        }

        // GET /lifecycle → intent별 lifecycle 상태 (남은 시간 등)
        if method == "GET" && path == "/lifecycle" {
            let lc = self.lifecycle.lock().unwrap();
            return (200, lc.status_json());
        }

        // GET /deficiencies → IntentGraph 결핍 분석 보고서
        if method == "GET" && path == "/deficiencies" {
            return (200, DeficiencyDetector::report_json(&self.graph));
        }

        // GET /reload/status → hot-reload 상태
        if method == "GET" && path == "/reload/status" {
            return match &self.reloader {
                Some(r) => (200, r.status_json()),
                None => (200, serde_json::json!({
                    "enabled": false,
                    "message": "hot-reload가 활성화되지 않았습니다 (--serve <file.fl> 로 실행 시 활성화)"
                })),
            };
        }

        // GET /federation → 소스 파일 목록 상태
        if method == "GET" && path == "/federation" {
            return match &self.federation {
                Some(f) => {
                    let fm = f.lock().unwrap();
                    (200, fm.status_json())
                }
                None => (200, serde_json::json!({
                    "enabled": false,
                    "message": "federation이 활성화되지 않았습니다"
                })),
            };
        }

        // GET /federation/merge → 현재 소스들 합성 결과
        if method == "GET" && path == "/federation/merge" {
            return match &self.federation {
                Some(f) => {
                    let fm = f.lock().unwrap();
                    let result = fm.merge();
                    (200, result.to_json())
                }
                None => (400, serde_json::json!({ "error": "federation 비활성화 상태" })),
            };
        }

        // GET /emit?target=ts|go|sql|openapi|json|summary
        // GET /emit/typescript, /emit/go, /emit/sql, /emit/openapi
        if method == "GET" && (path == "/emit" || path.starts_with("/emit/")) {
            let target_str = if path.starts_with("/emit/") {
                path.trim_start_matches("/emit/")
            } else {
                "json"
            };
            let target = EmitTarget::from_str(target_str)
                .unwrap_or(EmitTarget::Json);

            let content_type = match &target {
                EmitTarget::OpenApi    => "yaml",
                EmitTarget::Json       => "json",
                _                      => "text",
            };
            let code = emitter::emit(&self.graph, target);
            return (200, serde_json::json!({
                "content_type": content_type,
                "code": code,
                "lines": code.lines().count(),
            }));
        }

        // GET /snapshot → 스냅샷 상태
        if method == "GET" && path == "/snapshot" {
            return match &self.persist {
                Some(pm) => (200, pm.status_json()),
                None     => (200, serde_json::json!({
                    "enabled": false,
                    "message": "영속화가 활성화되지 않았습니다 (--persist <file> 로 실행 시 활성화)"
                })),
            };
        }

        // POST /snapshot → 수동 스냅샷 저장
        if method == "POST" && path == "/snapshot" {
            return match &self.persist {
                None => (400, serde_json::json!({ "error": "영속화 비활성화 상태" })),
                Some(pm) => {
                    match pm.save(db) {
                        Ok(()) => (200, serde_json::json!({
                            "ok": true,
                            "save_count": pm.save_count(),
                            "path": pm.config.path.to_str().unwrap_or("?"),
                            "size_bytes": pm.file_size_bytes(),
                        })),
                        Err(e) => (500, serde_json::json!({ "error": e })),
                    }
                }
            };
        }

        // GET /mutations → mutation 이력
        if method == "GET" && path == "/mutations" {
            let eng = self.mutation.lock().unwrap();
            return (200, eng.log_json());
        }

        // POST /mutate → graph 즉시 변경 (routes 재생성 포함)
        if method == "POST" && path == "/mutate" {
            let op = match MutationOp::from_json(
                &serde_json::from_str::<serde_json::Value>(body)
                    .unwrap_or(serde_json::Value::Null)
            ) {
                Ok(op) => op,
                Err(e) => return (400, serde_json::json!({ "error": e })),
            };

            let intent_name = op.target_intent().to_string();
            let op_kind = op.kind_str();
            let eng = Arc::clone(&self.mutation);
            let (success, msg) = eng.lock().unwrap().apply(&mut self.graph, op);

            if success {
                // 라우트 재생성 (graph 변경 반영)
                self.routes = Self::build_routes(&self.graph);

                // 이벤트 발행
                if let Some(bus) = &self.event_bus {
                    bus.publish(DbEvent::new(
                        EventKind::SchemaChange,
                        &intent_name,
                        "",
                        None,
                        serde_json::json!({ "op": op_kind, "message": msg }),
                    ));
                }

                return (200, serde_json::json!({
                    "ok": true,
                    "op": op_kind,
                    "intent": intent_name,
                    "message": msg,
                }));
            } else {
                return (400, serde_json::json!({ "error": msg }));
            }
        }

        // POST /reload → 수동 강제 리로드 (결과는 서버 측 교체 후 반영)
        if method == "POST" && path == "/reload" {
            return match &self.reloader {
                None => (400, serde_json::json!({ "error": "hot-reload 비활성화 상태" })),
                Some(r) => match r.force_reload() {
                    Ok(graph) => (200, serde_json::json!({
                        "ok": true,
                        "reload_count": r.reload_count(),
                        "intents": graph.intents.iter().map(|i| &i.name).collect::<Vec<_>>(),
                        "message": "리로드 완료. 다음 요청부터 새 라우트가 적용됩니다.",
                    })),
                    Err(e) => (500, serde_json::json!({ "error": e })),
                },
            };
        }

        // GET /{intent}/view/{view}       → HTML 페이지
        // GET /{intent}/view/{view}/nodes → FreeWire 노드 JSON
        let segments: Vec<&str> = path.trim_start_matches('/').split('/').collect();
        if method == "GET" && segments.len() >= 3 && segments[1] == "view" {
            let intent_name = segments[0];
            let view_name = segments[2];
            let renderer = ViewRenderer::new(&self.graph);

            if segments.len() == 4 && segments[3] == "nodes" {
                return match renderer.render_nodes(intent_name, view_name) {
                    Some(json) => (200, json),
                    None => (404, serde_json::json!({ "error": format!("view '{}' 없음", view_name) })),
                };
            } else if segments.len() == 3 {
                return match renderer.render_html(intent_name, view_name) {
                    Some(html) => {
                        // HTML 응답은 특수 마커로 감싸서 서버에서 처리
                        (200, serde_json::json!({ "_html": html }))
                    }
                    None => (404, serde_json::json!({ "error": format!("view '{}' 없음", view_name) })),
                };
            }
        }

        // 라우트 매칭
        let route = self.routes.iter().find(|r| r.method == method && r.path == path);

        match route {
            None => (404, serde_json::json!({
                "error": format!("라우트 없음: {} {}", method, path)
            })),
            Some(route) => {
                if method == "GET" {
                    // _select_ 라우트
                    let schema_name = route.action.strip_prefix("_select_").unwrap_or("");
                    match db.select_all(schema_name) {
                        Ok(rows) => (200, serde_json::json!({
                            "table": schema_name,
                            "count": rows.len(),
                            "rows": codec::rows_to_json(&rows),
                        })),
                        Err(e) => (500, serde_json::json!({ "error": e.to_string() })),
                    }
                } else {
                    // POST → action 실행
                    let args = match codec::parse_args(body, &route.params) {
                        Ok(a) => a,
                        Err(e) => return (400, serde_json::json!({ "error": e })),
                    };

                    // IntentGraph에서 action 찾기
                    let action = self.graph.intents.iter()
                        .find(|i| i.name == route.intent)
                        .and_then(|i| i.actions.iter().find(|a| a.name == route.action));

                    match action {
                        None => (500, serde_json::json!({
                            "error": format!("action '{}' 없음", route.action)
                        })),
                        Some(action) => {
                            let mut executor = ActionExecutor::new(db);
                            match executor.run(action, args) {
                                Ok(result) => (200, serde_json::json!({
                                    "ok": true,
                                    "action": route.action,
                                    "result": codec::value_to_json(&result),
                                })),
                                Err(e) => (500, serde_json::json!({
                                    "error": e.to_string()
                                })),
                            }
                        }
                    }
                }
            }
        }
    }
