use world_engine::migration::{
    Migration, MigrationEngine, MigrationKind,
    add_field_migration, remove_field_migration, rename_field_migration,
};

fn parse_fl() -> world_engine::IntentGraph {
    world_engine::parse(r#"
intent Catalog {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id:   uuid   @primary,
        name: string @required,
    }
    action list() { return 0; }
}
"#).unwrap()
}

// ─── MigrationKind ────────────────────────────────────────

#[test]
fn test_kind_as_str() {
    assert_eq!(MigrationKind::AddField.as_str(), "add_field");
    assert_eq!(MigrationKind::RemoveField.as_str(), "remove_field");
    assert_eq!(MigrationKind::RenameField.as_str(), "rename_field");
    assert_eq!(MigrationKind::AddIntent.as_str(), "add_intent");
    assert_eq!(MigrationKind::Custom("x".into()).as_str(), "x");
}

#[test]
fn test_kind_from_str() {
    assert_eq!(MigrationKind::from_str("add_field"),    MigrationKind::AddField);
    assert_eq!(MigrationKind::from_str("remove_field"), MigrationKind::RemoveField);
    assert_eq!(MigrationKind::from_str("rename_field"), MigrationKind::RenameField);
    assert_eq!(MigrationKind::from_str("custom_x"),     MigrationKind::Custom("custom_x".into()));
}

// ─── Migration ───────────────────────────────────────────

#[test]
fn test_migration_new() {
    let m = Migration::new(
        1, "Add price field",
        MigrationKind::AddField,
        serde_json::json!({"op":"add_field","intent":"X","schema":"Y","field_name":"price","field_type":"f64"}),
    );
    assert_eq!(m.version, 1);
    assert_eq!(m.description, "Add price field");
    assert!(!m.is_applied());
    assert!(m.checksum > 0);
}

#[test]
fn test_migration_to_json() {
    let m = Migration::new(2, "desc", MigrationKind::RemoveField, serde_json::json!({}));
    let j = m.to_json();
    assert_eq!(j["version"].as_u64().unwrap(), 2);
    assert_eq!(j["kind"].as_str().unwrap(), "remove_field");
    assert_eq!(j["applied"].as_bool().unwrap(), false);
}

#[test]
fn test_migration_from_json() {
    let j = serde_json::json!({
        "version": 3,
        "description": "test",
        "kind": "add_field",
        "payload": {"op":"add_field","intent":"A","schema":"B","field_name":"qty","field_type":"u32"},
    });
    let m = Migration::from_json(&j).unwrap();
    assert_eq!(m.version, 3);
    assert_eq!(m.kind, MigrationKind::AddField);
}

#[test]
fn test_migration_checksum_stable() {
    let p = serde_json::json!({"op":"add_field"});
    let m1 = Migration::new(1, "x", MigrationKind::AddField, p.clone());
    let m2 = Migration::new(1, "x", MigrationKind::AddField, p.clone());
    assert_eq!(m1.checksum, m2.checksum);
}

#[test]
fn test_migration_checksum_differs_for_different_versions() {
    let p = serde_json::json!({"op":"add_field"});
    let m1 = Migration::new(1, "x", MigrationKind::AddField, p.clone());
    let m2 = Migration::new(2, "x", MigrationKind::AddField, p.clone());
    assert_ne!(m1.checksum, m2.checksum);
}

// ─── 편의 함수 ────────────────────────────────────────────

#[test]
fn test_add_field_migration_helper() {
    let m = add_field_migration(1, "add price", "Shop", "Item", "price", "f64");
    assert_eq!(m.version, 1);
    assert_eq!(m.kind, MigrationKind::AddField);
    assert_eq!(m.payload["op"].as_str().unwrap(), "add_field");
    assert_eq!(m.payload["field_name"].as_str().unwrap(), "price");
}

#[test]
fn test_remove_field_migration_helper() {
    let m = remove_field_migration(2, "remove old", "Shop", "Item", "deprecated");
    assert_eq!(m.kind, MigrationKind::RemoveField);
    assert_eq!(m.payload["field_name"].as_str().unwrap(), "deprecated");
}

#[test]
fn test_rename_field_migration_helper() {
    let m = rename_field_migration(3, "rename", "Shop", "Item", "old_name", "new_name");
    assert_eq!(m.kind, MigrationKind::RenameField);
    assert_eq!(m.payload["old_name"].as_str().unwrap(), "old_name");
    assert_eq!(m.payload["new_name"].as_str().unwrap(), "new_name");
}

// ─── MigrationEngine ──────────────────────────────────────

#[test]
fn test_apply_add_field() {
    let mut graph = parse_fl();
    let mut eng = MigrationEngine::new("test-plan");
    eng = eng.add(add_field_migration(1, "add price", "Catalog", "Product", "price", "f64"));
    let results = eng.apply_all(&mut graph);
    assert_eq!(results.len(), 1);
    assert!(results[0].success, "실패: {}", results[0].message);
}

#[test]
fn test_apply_marks_as_applied() {
    let mut graph = parse_fl();
    let mut eng = MigrationEngine::new("p");
    eng = eng.add(add_field_migration(1, "add qty", "Catalog", "Product", "qty", "u32"));
    eng.apply_all(&mut graph);
    assert!(eng.plan.steps[0].is_applied());
}

#[test]
fn test_apply_already_applied_idempotent() {
    let mut graph = parse_fl();
    let mut eng = MigrationEngine::new("p");
    eng = eng.add(add_field_migration(1, "add stock", "Catalog", "Product", "stock", "u32"));
    eng.apply_all(&mut graph);

    // 두 번 적용해도 ok (이미 적용됨 메시지)
    let res = eng.apply_one(1, &mut graph);
    assert!(res.success);
    assert!(res.message.contains("이미 적용"));
}

#[test]
fn test_apply_up_to_version() {
    let mut graph = parse_fl();
    let mut eng = MigrationEngine::new("p")
        .add(add_field_migration(1, "v1", "Catalog", "Product", "price", "f64"))
        .add(add_field_migration(2, "v2", "Catalog", "Product", "qty",   "u32"))
        .add(add_field_migration(3, "v3", "Catalog", "Product", "tags",  "string"));

    let results = eng.apply_up_to(2, &mut graph);
    assert_eq!(results.len(), 2);
    assert!(results.iter().all(|r| r.success));

    // v3는 아직 미적용
    assert!(!eng.plan.steps[2].is_applied());
}

#[test]
fn test_plan_pending_and_applied() {
    let mut graph = parse_fl();
    let mut eng = MigrationEngine::new("p")
        .add(add_field_migration(1, "v1", "Catalog", "Product", "price", "f64"))
        .add(add_field_migration(2, "v2", "Catalog", "Product", "qty",   "u32"));

    eng.apply_one(1, &mut graph);
    assert_eq!(eng.plan.applied_steps().len(), 1);
    assert_eq!(eng.plan.pending_steps().len(), 1);
}

#[test]
fn test_plan_is_complete() {
    let mut graph = parse_fl();
    let mut eng = MigrationEngine::new("p")
        .add(add_field_migration(1, "v1", "Catalog", "Product", "price", "f64"));
    assert!(!eng.plan.is_complete());
    eng.apply_all(&mut graph);
    assert!(eng.plan.is_complete());
}

#[test]
fn test_plan_next_version() {
    let eng = MigrationEngine::new("p")
        .add(add_field_migration(5, "v5", "A", "B", "f", "f64"));
    assert_eq!(eng.plan.next_version(), 6);
}

#[test]
fn test_status_json() {
    let eng = MigrationEngine::new("my-plan")
        .add(add_field_migration(1, "v1", "A", "B", "f", "f64"));
    let j = eng.status_json();
    assert_eq!(j["name"].as_str().unwrap(), "my-plan");
    assert_eq!(j["total"].as_u64().unwrap(), 1);
    assert_eq!(j["applied"].as_u64().unwrap(), 0);
    assert_eq!(j["complete"].as_bool().unwrap(), false);
}

#[test]
fn test_unknown_version_returns_error() {
    let mut graph = parse_fl();
    let mut eng = MigrationEngine::new("p");
    let res = eng.apply_one(99, &mut graph);
    assert!(!res.success);
    assert!(res.message.contains("없음"));
}

// ─── Router 엔드포인트 ─────────────────────────────────────

#[test]
fn test_router_migrate_endpoint() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let mut db = result.db;

    let body = serde_json::json!({
        "plan": "v1-migration",
        "steps": [
            {
                "version": 1,
                "description": "Add price field",
                "kind": "add_field",
                "payload": {
                    "op": "add_field",
                    "intent": "Catalog",
                    "schema": "Product",
                    "field_name": "price",
                    "field_type": "f64"
                }
            }
        ]
    }).to_string();

    let (status, json) = router.handle(&mut db, "POST", "/migrate", &body);
    assert_eq!(status, 200, "migrate 실패: {:?}", json);
    assert!(json["ok"].as_bool().unwrap());
    assert_eq!(json["applied"].as_u64().unwrap(), 1);
}

#[test]
fn test_router_migrate_multiple_steps() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
