    metrics: &DashboardMetrics,
    version: &str,
) -> String {
    let intent_rows = graph.intents.iter().map(|intent| {
        let schemas = intent.schemas.iter()
            .map(|s| {
                let fields = s.fields.iter()
                    .map(|f| format!(
                        "<span class='field'>{}: <em>{}</em>{}</span>",
                        f.name,
                        f.field_type,
                        if f.attrs.contains(&"primary".to_string()) { " <sup>PK</sup>" }
                        else if f.attrs.contains(&"required".to_string()) { " <sup>*</sup>" }
                        else { "" }
                    ))
                    .collect::<Vec<_>>()
                    .join(", ");

                // record count
                let count = metrics.record_counts.iter()
                    .find(|(t, _)| t == &format!("{}.{}", intent.name, s.name))
                    .map(|(_, c)| *c)
                    .unwrap_or(0);

                format!(
                    "<div class='schema'><strong>{}</strong> \
                     <span class='badge'>{} rows</span><br><span class='fields'>{}</span></div>",
                    s.name, count, fields
                )
            })
            .collect::<Vec<_>>()
            .join("");

        let actions = intent.actions.iter()
            .map(|a| format!("<span class='action'>{}()</span>", a.name))
            .collect::<Vec<_>>()
            .join(" ");

        format!(
            "<tr><td><strong>{}</strong></td><td>{}</td><td class='actions'>{}</td></tr>",
            intent.name, schemas, actions
        )
    }).collect::<Vec<_>>().join("\n");

    let status_badges = format!(
        "{} {} {}",
        badge("Auth",   metrics.auth_enabled,   "green", "gray"),
        badge("RateLimit", metrics.rl_enabled,  "green", "gray"),
        badge("Events", metrics.events_enabled, "green", "gray"),
    );

    format!(r#"<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>World Engine Dashboard</title>
<style>
  :root {{
    --bg: #0f1117; --surface: #1a1d27; --border: #2d3048;
    --text: #e2e8f0; --muted: #64748b; --accent: #6366f1;
    --green: #22c55e; --yellow: #eab308; --red: #ef4444;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{ background: var(--bg); color: var(--text); font-family: 'Segoe UI', sans-serif; padding: 1.5rem; }}
  h1 {{ font-size: 1.6rem; color: var(--accent); margin-bottom: .25rem; }}
  .subtitle {{ color: var(--muted); font-size: .85rem; margin-bottom: 1.5rem; }}
  .cards {{ display: flex; gap: 1rem; flex-wrap: wrap; margin-bottom: 1.5rem; }}
  .card {{ background: var(--surface); border: 1px solid var(--border); border-radius: .75rem;
           padding: 1rem 1.5rem; min-width: 120px; text-align: center; }}
  .card .num {{ font-size: 2rem; font-weight: 700; color: var(--accent); }}
  .card .label {{ font-size: .75rem; color: var(--muted); margin-top: .25rem; }}
  .status-row {{ margin-bottom: 1.5rem; display: flex; gap: .5rem; align-items: center; flex-wrap: wrap; }}
  .badge {{ padding: .2rem .6rem; border-radius: 999px; font-size: .75rem; font-weight: 600; }}
  .badge.on  {{ background: #14532d; color: #86efac; }}
  .badge.off {{ background: #1f2937; color: #6b7280; }}
  table {{ width: 100%; border-collapse: collapse; background: var(--surface);
           border: 1px solid var(--border); border-radius: .75rem; overflow: hidden; }}
  th {{ background: var(--border); padding: .75rem 1rem; text-align: left;
        font-size: .8rem; color: var(--muted); text-transform: uppercase; }}
  td {{ padding: .75rem 1rem; border-top: 1px solid var(--border); vertical-align: top; }}
  .schema {{ margin-bottom: .5rem; }}
  .fields {{ color: var(--muted); font-size: .8rem; }}
  .field {{ margin-right: .5rem; }}
  em {{ color: #93c5fd; font-style: normal; }}
  sup {{ color: var(--yellow); font-size: .65rem; }}
  .actions {{ color: #a78bfa; font-size: .85rem; }}
  .action {{ margin-right: .4rem; }}
  footer {{ margin-top: 2rem; color: var(--muted); font-size: .75rem; text-align: center; }}
  .refresh-btn {{ background: var(--accent); color: #fff; border: none; padding: .4rem .9rem;
                  border-radius: .4rem; cursor: pointer; font-size: .8rem; margin-left: auto; }}
</style>
</head>
<body>
<div style="display:flex;align-items:baseline;gap:1rem;margin-bottom:.25rem">
  <h1>⚡ World Engine</h1>
  <span style="color:var(--muted);font-size:.8rem">v{version}</span>
  <button class="refresh-btn" onclick="location.reload()">새로고침</button>
</div>
<p class="subtitle">Intent-Driven Computing Dashboard · uptime {uptime}s</p>

<div class="cards">
  <div class="card"><div class="num">{intents}</div><div class="label">Intents</div></div>
  <div class="card"><div class="num">{schemas}</div><div class="label">Schemas</div></div>
  <div class="card"><div class="num">{actions}</div><div class="label">Actions</div></div>
  <div class="card"><div class="num">{routes}</div><div class="label">Routes</div></div>
</div>

<div class="status-row">
  <span style="color:var(--muted);font-size:.8rem">기능:</span>
  {status}
</div>

<table>
  <thead>
    <tr>
      <th>Intent</th>
      <th>Schemas & Fields</th>
      <th>Actions</th>
    </tr>
  </thead>
  <tbody>
    {rows}
  </tbody>
</table>

<footer>World Engine Dashboard · <a href="/routes" style="color:var(--accent)">Routes</a> ·
<a href="/health" style="color:var(--accent)">Health</a> ·
<a href="/dashboard/metrics" style="color:var(--accent)">JSON Metrics</a></footer>

<script>
  // 30초 자동 갱신
  setTimeout(() => location.reload(), 30000);
</script>
</body>
</html>"#,
        version  = version,
        uptime   = metrics.uptime_secs,
        intents  = metrics.intent_count,
        schemas  = metrics.schema_count,
        actions  = metrics.action_count,
        routes   = metrics.route_count,
        status   = status_badges,
        rows     = intent_rows,
    )
}

fn badge(label: &str, on: bool, _on_color: &str, _off_color: &str) -> String {
    let cls = if on { "on" } else { "off" };
    let icon = if on { "✓" } else { "–" };
    format!("<span class='badge {}'>{} {}</span>", cls, icon, label)
}

// ─── KimDB 레코드 수 수집 ─────────────────────────────────

pub fn collect_record_counts(graph: &IntentGraph, db: &KimDB) -> Vec<(String, usize)> {
    let mut result = Vec::new();
    for intent in &graph.intents {
        for schema in &intent.schemas {
            let table_key = format!("{}.{}", intent.name, schema.name);
            let count = db.select(&intent.name, &schema.name, None).len();
            result.push((table_key, count));
        }
    }
    result
}

