  th {{ background: var(--border); padding: .75rem 1rem; text-align: left;
        font-size: .8rem; color: var(--muted); text-transform: uppercase; }}
  td {{ padding: .75rem 1rem; border-top: 1px solid var(--border); vertical-align: top; }}
  .schema {{ margin-bottom: .5rem; }}
  .fields {{ color: var(--muted); font-size: .8rem; }}
  .field {{ margin-right: .5rem; }}
  em {{ color: #93c5fd; font-style: normal; }}
  sup {{ color: var(--yellow); font-size: .65rem; }}
  .actions {{ color: #a78bfa; font-size: .85rem; }}
  .action {{ margin-right: .4rem; }}
  footer {{ margin-top: 2rem; color: var(--muted); font-size: .75rem; text-align: center; }}
  .refresh-btn {{ background: var(--accent); color: #fff; border: none; padding: .4rem .9rem;
                  border-radius: .4rem; cursor: pointer; font-size: .8rem; margin-left: auto; }}
</style>
</head>
<body>
<div style="display:flex;align-items:baseline;gap:1rem;margin-bottom:.25rem">
  <h1>⚡ World Engine</h1>
  <span style="color:var(--muted);font-size:.8rem">v{version}</span>
  <button class="refresh-btn" onclick="location.reload()">새로고침</button>
</div>
<p class="subtitle">Intent-Driven Computing Dashboard · uptime {uptime}s</p>

<div class="cards">
  <div class="card"><div class="num">{intents}</div><div class="label">Intents</div></div>
  <div class="card"><div class="num">{schemas}</div><div class="label">Schemas</div></div>
  <div class="card"><div class="num">{actions}</div><div class="label">Actions</div></div>
  <div class="card"><div class="num">{routes}</div><div class="label">Routes</div></div>
</div>

<div class="status-row">
  <span style="color:var(--muted);font-size:.8rem">기능:</span>
  {status}
</div>

<table>
  <thead>
    <tr>
      <th>Intent</th>
      <th>Schemas & Fields</th>
      <th>Actions</th>
    </tr>
  </thead>
  <tbody>
    {rows}
  </tbody>
</table>

<footer>World Engine Dashboard · <a href="/routes" style="color:var(--accent)">Routes</a> ·
<a href="/health" style="color:var(--accent)">Health</a> ·
<a href="/dashboard/metrics" style="color:var(--accent)">JSON Metrics</a></footer>

<script>
  // 30초 자동 갱신
  setTimeout(() => location.reload(), 30000);
</script>
</body>
</html>"#,
        version  = version,
        uptime   = metrics.uptime_secs,
        intents  = metrics.intent_count,
        schemas  = metrics.schema_count,
        actions  = metrics.action_count,
        routes   = metrics.route_count,
        status   = status_badges,
        rows     = intent_rows,
    )
}

fn badge(label: &str, on: bool, _on_color: &str, _off_color: &str) -> String {
    let cls = if on { "on" } else { "off" };
    let icon = if on { "✓" } else { "–" };
    format!("<span class='badge {}'>{} {}</span>", cls, icon, label)
}

// ─── KimDB 레코드 수 수집 ─────────────────────────────────

pub fn collect_record_counts(graph: &IntentGraph, db: &KimDB) -> Vec<(String, usize)> {
    let mut result = Vec::new();
    for intent in &graph.intents {
        for schema in &intent.schemas {
            let table_key = format!("{}.{}", intent.name, schema.name);
            let count = db.select(&intent.name, &schema.name, None).len();
            result.push((table_key, count));
        }
    }
    result
}

