use crate::ast::{IntentGraph, Annotation};
use crate::synthesizer::kimdb::KimDB;

// ─── DashboardMetrics ─────────────────────────────────────

#[derive(Debug, Clone)]
pub struct DashboardMetrics {
    pub intent_count:  usize,
    pub schema_count:  usize,
    pub action_count:  usize,
    pub route_count:   usize,
    pub record_counts: Vec<(String, usize)>, // (table_name, count)
    pub auth_enabled:  bool,
    pub rl_enabled:    bool,
    pub events_enabled: bool,
    pub uptime_secs:   u64,
}

impl DashboardMetrics {
    pub fn to_json(&self) -> serde_json::Value {
        let tables: serde_json::Value = self.record_counts.iter()
            .map(|(t, c)| serde_json::json!({ "table": t, "count": c }))
            .collect::<Vec<_>>()
            .into();
        serde_json::json!({
            "intents":        self.intent_count,
            "schemas":        self.schema_count,
            "actions":        self.action_count,
            "routes":         self.route_count,
            "auth_enabled":   self.auth_enabled,
            "rl_enabled":     self.rl_enabled,
            "events_enabled": self.events_enabled,
            "uptime_secs":    self.uptime_secs,
            "tables":         tables,
        })
    }
}

// ─── HTML 생성 ────────────────────────────────────────────

pub fn render_dashboard(
    graph: &IntentGraph,
    metrics: &DashboardMetrics,
    version: &str,
) -> String {
    let intent_rows = graph.intents.iter().map(|intent| {
        let schemas = intent.schemas.iter()
            .map(|s| {
                let fields = s.fields.iter()
                    .map(|f| {
                        let is_pk  = f.annotations.iter().any(|a| matches!(a, Annotation::Primary));
                        let is_req = f.annotations.iter().any(|a| matches!(a, Annotation::Required));
                        format!(
                            "<span class='field'>{}: <em>{}</em>{}</span>",
                            f.name,
                            f.field_type,
                            if is_pk { " <sup>PK</sup>" }
                            else if is_req { " <sup>*</sup>" }
                            else { "" }
                        )
                    })
                    .collect::<Vec<_>>()
                    .join(", ");

                // record count
                let count = metrics.record_counts.iter()
                    .find(|(t, _)| t == &format!("{}.{}", intent.name, s.name))
                    .map(|(_, c)| *c)
                    .unwrap_or(0);

                format!(
                    "<div class='schema'><strong>{}</strong> \
                     <span class='badge'>{} rows</span><br><span class='fields'>{}</span></div>",
                    s.name, count, fields
                )
            })
            .collect::<Vec<_>>()
            .join("");

        let actions = intent.actions.iter()
            .map(|a| format!("<span class='action'>{}()</span>", a.name))
            .collect::<Vec<_>>()
            .join(" ");

        format!(
            "<tr><td><strong>{}</strong></td><td>{}</td><td class='actions'>{}</td></tr>",
            intent.name, schemas, actions
        )
    }).collect::<Vec<_>>().join("\n");

    let status_badges = format!(
        "{} {} {}",
        badge("Auth",   metrics.auth_enabled,   "green", "gray"),
        badge("RateLimit", metrics.rl_enabled,  "green", "gray"),
        badge("Events", metrics.events_enabled, "green", "gray"),
    );

    format!(r#"<!DOCTYPE html>
<html lang="ko">
