#[test]
fn test_metrics_to_json() {
    let m = DashboardMetrics {
        intent_count:   2,
        schema_count:   2,
        action_count:   3,
        route_count:    5,
        record_counts:  vec![("Shop.Product".into(), 10)],
        auth_enabled:   true,
        rl_enabled:     false,
        events_enabled: true,
        uptime_secs:    42,
    };
    let j = m.to_json();
    assert_eq!(j["intents"].as_u64().unwrap(),  2);
    assert_eq!(j["schemas"].as_u64().unwrap(),  2);
    assert_eq!(j["actions"].as_u64().unwrap(),  3);
    assert_eq!(j["routes"].as_u64().unwrap(),   5);
    assert_eq!(j["auth_enabled"].as_bool().unwrap(),   true);
    assert_eq!(j["rl_enabled"].as_bool().unwrap(),     false);
    assert_eq!(j["events_enabled"].as_bool().unwrap(), true);
    assert_eq!(j["uptime_secs"].as_u64().unwrap(), 42);
    assert_eq!(j["tables"][0]["table"].as_str().unwrap(), "Shop.Product");
    assert_eq!(j["tables"][0]["count"].as_u64().unwrap(), 10);
}

