#[test]
fn test_collect_record_counts_empty() {
    use world_engine::synthesizer::Synthesizer;
    let graph = make_graph();
    let result = Synthesizer::synthesize(&graph);
    let counts = collect_record_counts(&graph, &result.db);
    // 모두 0 (아직 삽입 없음)
    assert!(counts.iter().all(|(_, c)| *c == 0));
}

#[test]
fn test_collect_record_counts_after_insert() {
    use world_engine::synthesizer::Synthesizer;
    let graph = world_engine::parse(r#"
intent Inv {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Item { id: uuid @primary, name: string @required, }
    action list() { return 0; }
}
"#).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let mut db = result.db;
    let mut row = std::collections::HashMap::new();
    row.insert("id".to_string(), world_engine::synthesizer::kimdb::Value::Str("x1".into()));
    row.insert("name".to_string(), world_engine::synthesizer::kimdb::Value::Str("Widget".into()));
    db.insert("Inv.Item", row).unwrap();

    let counts = collect_record_counts(&graph, &db);
    let item_count = counts.iter().find(|(t, _)| t == "Inv.Item").map(|(_, c)| *c).unwrap_or(0);
    assert_eq!(item_count, 1);
}

