#[test]
fn test_router_dashboard_endpoint() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = make_graph();
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/dashboard", "");
    assert_eq!(status, 200);
    // HTML 응답은 __html__ 키에 담아 반환
    let html = json["__html__"].as_str().unwrap();
    assert!(html.contains("<!DOCTYPE html>"));
    assert!(html.contains("World Engine"));
}

