#[test]
fn e2e_schema_evolution() {
    let graph = parse(r#"
intent Blog {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Post { id: uuid @primary, title: string @required, }
    action publish() { return 0; }
}
"#).unwrap();
