// ─── 시나리오 6: 전체 기능 통합 (Auth+Events+Migration+Dashboard) ─

#[test]
fn e2e_full_feature_integration() {
    let graph = parse(r#"
intent Platform {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema User { id: uuid @primary, name: string @required, }
    action register() { return 0; }
}
"#).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let mut db = result.db;

    let am = Arc::new(
        AuthManager::new(AuthConfig::new("platform-secret"))
            .with_rate_limit(RateLimitConfig::new(60, 10, 20, 1000))
    );
    let admin_key = am.issue_api_key("admin", Permission::Admin);
    let bus = new_event_bus(200);

    let mut router = Router::from_graph(graph)
        .with_auth(Arc::clone(&am))
        .with_event_bus(Arc::clone(&bus));

    let ah = hdrs(&[("x-api-key", &admin_key)]);
    let mut db_ref = &mut db;

    // Step 1: 인증 상태 확인
    let (s, j) = router.handle(db_ref, "GET", "/auth/status", "");
    assert_eq!(s, 200);
    assert!(j["enabled"].as_bool().unwrap());
    assert!(j["rate_limiting"].as_bool().unwrap());

    // Step 2: 새 API Key 발급
    let (s, j) = router.handle_with_headers(
        db_ref, "POST", "/auth/keys",
        r#"{"label":"service","permission":"readwrite"}"#, &ah
    );
    assert_eq!(s, 200);
    let svc_key = j["key"].as_str().unwrap().to_string();

    // Step 3: Token 발급
    let (s, j) = router.handle_with_headers(
        db_ref, "POST", "/auth/token",
        r#"{"subject":"service"}"#, &ah
    );
    assert_eq!(s, 200);
    let token = j["token"].as_str().unwrap().to_string();

    // Step 4: Migration 적용
    let migrate_body = serde_json::json!({
        "plan": "platform-v1",
        "steps": [{
            "version": 1,
            "description": "Add role field",
            "kind": "add_field",
            "payload": {
                "op": "add_field", "intent": "Platform",
                "schema": "User", "field_name": "role", "field_type": "string"
            }
        }]
    }).to_string();
    let (s, j) = router.handle_with_headers(db_ref, "POST", "/migrate", &migrate_body, &ah);
    assert_eq!(s, 200);
    assert!(j["ok"].as_bool().unwrap());

    // Step 5: Mutation으로 이벤트 발행 확인
    let sh = hdrs(&[("x-api-key", &svc_key)]);
    router.handle_with_headers(
        db_ref, "POST", "/mutate",
        r#"{"op":"add_field","intent":"Platform","schema":"User","field_name":"verified","field_type":"bool"}"#,
        &sh
    );
    let events = bus.recent_events(10);
    assert!(!events.is_empty());

    // Step 6: Rate Limit 통계
    let (s, j) = router.handle(db_ref, "GET", "/auth/ratelimit", "");
    assert_eq!(s, 200);
    assert!(j["enabled"].as_bool().unwrap());

    // Step 7: Dashboard 최종 상태
    let (s, j) = router.handle(db_ref, "GET", "/dashboard/metrics", "");
    assert_eq!(s, 200);
    assert_eq!(j["auth_enabled"].as_bool().unwrap(), true);
    assert_eq!(j["events_enabled"].as_bool().unwrap(), true);
    assert_eq!(j["rl_enabled"].as_bool().unwrap(), true);

    // Step 8: 토큰 폐기 후 접근 불가
    let (s, j) = router.handle_with_headers(
        db_ref, "POST", "/auth/revoke",
        &serde_json::json!({"token": token}).to_string(), &ah
    );
    assert_eq!(s, 200);
    assert!(j["ok"].as_bool().unwrap());
}

