    assert_eq!(s, 200);
    assert_eq!(j["auth_enabled"].as_bool().unwrap(), true);
    assert_eq!(j["events_enabled"].as_bool().unwrap(), true);
    assert_eq!(j["rl_enabled"].as_bool().unwrap(), true);

    // Step 8: 토큰 폐기 후 접근 불가
    let (s, j) = router.handle_with_headers(
        db_ref, "POST", "/auth/revoke",
        &serde_json::json!({"token": token}).to_string(), &ah
    );
    assert_eq!(s, 200);
    assert!(j["ok"].as_bool().unwrap());
}

