    let tl      = collector.timeline.lock().unwrap();
    let metrics = collector.metrics.lock().unwrap();

    let success_rate = format!("{:.1}", metrics.success_rate());

    // 타임라인 HTML
    let timeline_items = tl.recent(50).iter().map(|r| {
        let meta = if r.metrics != serde_json::Value::Null && r.metrics != serde_json::json!({}) {
            format!("<pre class='meta'>{}</pre>",
                serde_json::to_string_pretty(&r.metrics).unwrap_or_default())
        } else { String::new() };

        format!(
            r#"<div class="tl-item {ok}">
  <div class="tl-dot" style="background:{color}"></div>
  <div class="tl-body">
    <div class="tl-header">
      <span class="tl-icon">{icon}</span>
      <span class="tl-title">{title}</span>
      <span class="tl-badge" style="background:{color}22;color:{color}">{kind}</span>
      <span class="tl-time">{time}</span>
    </div>
    <div class="tl-desc">{desc}</div>
    {meta}
  </div>
</div>"#,
            ok    = if r.success { "ok" } else { "fail" },
            color = r.kind.color(),
            icon  = r.kind.icon(),
            title = r.title,
            kind  = r.kind.as_str(),
            time  = r.relative_time(),
            desc  = r.description,
            meta  = meta,
        )
    }).collect::<Vec<_>>().join("\n");

    let timeline_empty = if tl.all().is_empty() {
        r#"<div class="empty">아직 기록된 이벤트가 없습니다.</div>"#
    } else { "" };

    // DB 테이블 현황
    let db_rows = if metrics.db_counts.is_empty() {
        "<tr><td colspan='2' style='color:var(--muted)'>테이블 없음</td></tr>".to_string()
    } else {
        metrics.db_counts.iter().map(|(t, c)| {
            format!("<tr><td>{}</td><td class='num-cell'>{}</td></tr>", t, c)
        }).collect::<Vec<_>>().join("\n")
    };

    format!(r#"<!DOCTYPE html>
